          "contentText": "{\n  \"querySummary\": {\n    \"businessConcept\": \"Expense automation for modern finance teams\",\n    \"candidateCount\": 10,\n    \"preferredTlds\": [\"com\", \"ai\", \"co\"]\n  },\n  \"recommendedNames\": [\n    {\n      \"name\": \"Ramp\",\n      \"strategy\": \"abstract\",\n      \"overallScore\": 92,\n      \"verdict\": \"strong_candidate\",\n      \"reasons\": [\n        \"short and memorable\",\n        \"clear upward-motion association\",\n        \"credible startup brand voice\"\n      ],\n      \"brandability\": {\n        \"memorability\": 10,\n        \"pronounceability\": 10,\n        \"spellability\": 10,\n        \"uniqueness\": 7,\n        \"meaningfulness\": 9\n      },\n      \"domainOptions\": [\n        {\n          \"domain\": \"ramp.com\",\n          \"tld\": \"com\",\n          \"availability\": \"unavailable\",\n          \"status\": \"unavailable\"\n        },\n        {\n          \"domain\": \"useramp.ai\",\n          \"tld\": \"ai\",\n          \"availability\": \"available\",\n          \"status\": \"available\"\n        }\n      ],\n      \"risks\": [\"exact-match .com unavailable\"],\n      \"bestDomain\": \"useramp.ai\"\n    }\n  ],\n  \"rejectedNames\": [\n    {\n      \"name\": \"Ramply\",\n      \"reasons\": [\n        \"weaker distinctiveness\",\n        \"suffix feels forced\",\n        \"domain path is less clean\"\n      ]\n    }\n  ]\n}\n",
